import{_ as a,o as n,c as p,a3 as t}from"./chunks/framework.bijRUqYl.js";const d=JSON.parse('{"title":"实体门店与餐饮提示词模板","description":"实体门店与餐饮的 5 条提示词模板：菜单描述、团购活动、排班、顾客投诉、私域群运营。","frontmatter":{"title":"实体门店与餐饮提示词模板","description":"实体门店与餐饮的 5 条提示词模板：菜单描述、团购活动、排班、顾客投诉、私域群运营。"},"headers":[],"relativePath":"community/prompts/实体门店与餐饮.md","filePath":"community/prompts/实体门店与餐饮.md"}'),e={name:"community/prompts/实体门店与餐饮.md"};function l(o,s,i,c,r,u){return n(),p("div",null,[...s[0]||(s[0]=[t(`<h1 id="🍜-实体门店与餐饮-·-5-条提示词模板" tabindex="-1">🍜 实体门店与餐饮 · 5 条提示词模板 <a class="header-anchor" href="#🍜-实体门店与餐饮-·-5-条提示词模板" aria-label="Permalink to &quot;🍜 实体门店与餐饮 · 5 条提示词模板&quot;">​</a></h1><blockquote><p>开店的活是&quot;碎&quot;的：菜单、活动、排班、投诉、发群。 这些活单件都不难，<strong>难在天天都有，还都得你一个人想</strong>。</p></blockquote><h2 id="本行三句话骨架" tabindex="-1">本行三句话骨架 <a class="header-anchor" href="#本行三句话骨架" aria-label="Permalink to &quot;本行三句话骨架&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>我开的是【什么店 / 位置 / 客单价 / 主要客群】。</span></span>
<span class="line"><span>帮我做【菜单 / 活动 / 排班 / 话术】，形式【…】。</span></span>
<span class="line"><span>按【我的实际条件：人手、成本、营业时间】来，不许给我一个我做不到的方案。</span></span></code></pre></div><hr><h2 id="_1-·-菜名与菜单描述-→-让人想点" tabindex="-1">1 · 菜名与菜单描述 → 让人想点 <a class="header-anchor" href="#_1-·-菜名与菜单描述-→-让人想点" aria-label="Permalink to &quot;1 · 菜名与菜单描述 → 让人想点&quot;">​</a></h2><p><strong>什么时候用</strong>：菜单上一堆&quot;番茄炒蛋&quot;&quot;小炒黄牛肉&quot;，谁都见过，谁都想不起来点。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>我的店：【品类 / 人均 / 客群，例如&quot;社区川菜馆，人均 60，家庭客为主&quot;】</span></span>
<span class="line"><span>这几道菜我要重写描述：【菜名 + 真实用料 + 做法特点 + 成本/定价】</span></span>
<span class="line"><span>我店里真正有优势的地方：【食材新鲜？火候？分量？辣度可调？】</span></span>
<span class="line"><span></span></span>
<span class="line"><span>帮我：</span></span>
<span class="line"><span>① 每道菜改一个好记的菜名（保留原菜名做副标题，避免客人看不懂）</span></span>
<span class="line"><span>② 每道菜写一句 12 字内的&quot;点它的理由&quot;</span></span>
<span class="line"><span>③ 写 2 句菜单上的小字描述（不吹牛，就写用料和做法）</span></span>
<span class="line"><span>④ 从这几道菜里，帮我挑出 3 道应该重点推的，并说明为什么</span></span>
<span class="line"><span>规矩：不许用&quot;秘制&quot;&quot;独家&quot;&quot;祖传&quot;这种词，除非我真的这么做过。</span></span></code></pre></div><p><strong>它给你</strong>：菜名 + 一句话理由 + 描述 + 主推建议。</p><hr><h2 id="_2-·-团购-促销活动方案-含-别亏-的规则设计" tabindex="-1">2 · 团购 / 促销活动方案（含&quot;别亏&quot;的规则设计） <a class="header-anchor" href="#_2-·-团购-促销活动方案-含-别亏-的规则设计" aria-label="Permalink to &quot;2 · 团购 / 促销活动方案（含&quot;别亏&quot;的规则设计）&quot;">​</a></h2><p><strong>什么时候用</strong>：要做活动，但上一个活动做完发现白忙一场。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>我的店：【品类 / 人均 / 日均客流 / 客单价 / 毛利率大概多少】</span></span>
<span class="line"><span>这次活动想解决什么：【拉新客 / 清库存 / 提客单 / 淡季引流】</span></span>
<span class="line"><span>我能接受的让利上限：【…元/人或…%】</span></span>
<span class="line"><span>可用资源：【人手几个 / 能上的时段 / 有没有平台资源】</span></span>
<span class="line"><span></span></span>
<span class="line"><span>帮我设计 3 个活动方案，每个方案写清：</span></span>
<span class="line"><span>① 活动内容（客人看到的是什么）</span></span>
<span class="line"><span>② 规则细节（使用时段、叠加规则、限量、有效期）</span></span>
<span class="line"><span>③ 我的成本与保本点怎么算（给公式和代入数字的过程）</span></span>
<span class="line"><span>④ 怎么防钻空子（这行最容易被薅的几个口子）</span></span>
<span class="line"><span>规矩：算不出来的地方明确说&quot;需要你补充 XX 数据&quot;，别替我假设。</span></span></code></pre></div><p><strong>它给你</strong>：3 个方案 + 保本算法 + 防漏规则。<strong>&quot;保本点&quot;这一栏是这份提示词的全部意义</strong>——不算清楚，活动就是赌博。</p><hr><h2 id="_3-·-排班表-按客流高峰反推" tabindex="-1">3 · 排班表（按客流高峰反推） <a class="header-anchor" href="#_3-·-排班表-按客流高峰反推" aria-label="Permalink to &quot;3 · 排班表（按客流高峰反推）&quot;">​</a></h2><p><strong>什么时候用</strong>：每周排班都要改，改完总有人不满意，高峰还是缺人。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>我的店：【营业时间 / 几个岗位 / 一共几个人 / 每人每周最多上几天】</span></span>
<span class="line"><span>客流规律：【周几到周几是高峰、几点到几点最忙、什么时段几乎没人】</span></span>
<span class="line"><span>每个人的限制：【谁只能上早班 / 谁请假 / 谁不能连着上晚班】</span></span>
<span class="line"><span></span></span>
<span class="line"><span>帮我排一周的班，输出成表格（行=人，列=周一到周日），并在下面写：</span></span>
<span class="line"><span>① 每天的高峰时段各安排了几个人</span></span>
<span class="line"><span>② 哪些时段是&quot;刚好够&quot;、哪些是&quot;偏紧&quot;，标出来</span></span>
<span class="line"><span>③ 如果某天有人临时请假，可以用哪个方案补位</span></span>
<span class="line"><span>规矩：必须满足每个人的限制条件；实在排不开就直接告诉我冲突在哪。</span></span></code></pre></div><p><strong>它给你</strong>：一张能直接贴到群里的排班表 + 风险提示。</p><hr><h2 id="_4-·-顾客投诉的现场处理话术" tabindex="-1">4 · 顾客投诉的现场处理话术 <a class="header-anchor" href="#_4-·-顾客投诉的现场处理话术" aria-label="Permalink to &quot;4 · 顾客投诉的现场处理话术&quot;">​</a></h2><p><strong>什么时候用</strong>：客人当着其他客人的面发火，你脑子里一片空白。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>事情经过：【照实写，包括我们确实哪里没做好】</span></span>
<span class="line"><span>客人现在的状态：【…】</span></span>
<span class="line"><span>周围情况：【有没有其他客人在看 / 是不是在群里发的 / 是不是在大众点评上写】</span></span>
<span class="line"><span></span></span>
<span class="line"><span>请分三层给我应对：</span></span>
<span class="line"><span>① &quot;现在这一分钟&quot;说什么（不超过 3 句，先让人坐下/先把火压住）</span></span>
<span class="line"><span>② &quot;接下来怎么解决&quot;（给两个方案，一个立刻见效、一个需要点时间）</span></span>
<span class="line"><span>③ &quot;事后怎么收尾&quot;（要不要私信道歉、要不要给补偿、怎么留个台阶）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>再给我一句&quot;如果对方要报警/要找平台&quot;时该说的话。</span></span>
<span class="line"><span>规矩：答应的事必须是我能做到的；不要让我承诺&quot;免单&quot;这种我可能不愿意的成本。</span></span></code></pre></div><p><strong>它给你</strong>：三句话 + 两个方案 + 收尾动作。</p><hr><h2 id="_5-·-私域群一周内容排期-不刷屏、也不冷场" tabindex="-1">5 · 私域群一周内容排期（不刷屏、也不冷场） <a class="header-anchor" href="#_5-·-私域群一周内容排期-不刷屏、也不冷场" aria-label="Permalink to &quot;5 · 私域群一周内容排期（不刷屏、也不冷场）&quot;">​</a></h2><p><strong>什么时候用</strong>：客人拉了群，但群里只有你发广告，没人回。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>我的群：【什么客人 / 多少人 / 我发过什么 / 为什么冷了】</span></span>
<span class="line"><span>我一周能发几条：【…条】</span></span>
<span class="line"><span>我能提供的东西：【新品 / 后厨日常 / 优惠 / 老板的一点想法】</span></span>
<span class="line"><span></span></span>
<span class="line"><span>帮我排一周的群内容（每天不超过 2 条），要求：</span></span>
<span class="line"><span>① 广告类内容最多占 1/3，其余是&quot;有用的&quot;或&quot;有人味儿的&quot;</span></span>
<span class="line"><span>② 每条给我可直接发的文案（含图建议：拍什么）</span></span>
<span class="line"><span>③ 每周设一个&quot;能引起回复&quot;的小互动（门槛要极低，回一个字就能参与）</span></span>
<span class="line"><span>④ 告诉我哪一条最容易冷场，怎么改</span></span>
<span class="line"><span>规矩：不许编&quot;我店里客人的真实反馈&quot;。</span></span></code></pre></div><p><strong>它给你</strong>：一周可发文案 + 拍摄建议 + 互动设计。</p><hr><h2 id="⚠️-这行的三条红线" tabindex="-1">⚠️ 这行的三条红线 <a class="header-anchor" href="#⚠️-这行的三条红线" aria-label="Permalink to &quot;⚠️ 这行的三条红线&quot;">​</a></h2><ol><li><strong>食品安全相关的话不能编</strong>：食材来源、无添加、当日现做、保质期——写错了是事故，不是文案问题。</li><li><strong>资质与承诺要真</strong>：许可证、加盟、连锁——涉及这些字的文案，发之前自己核一遍。</li><li><strong>客人隐私别外传</strong>：投诉的聊天记录、顾客照片，给 AI 处理前先去掉姓名和手机号。</li></ol><hr><p><strong>目录</strong>：<a href="/MoMAWork-/community/prompts/">← 回到行业提示词模板库</a> ｜ 下一个行业 → <strong><a href="/MoMAWork-/community/prompts/教育培训.html">教育培训</a></strong></p>`,34)])])}const g=a(e,[["render",l]]);export{d as __pageData,g as default};
